   SET max_id = (select max(id) FROM taxify_payment_order.inapp_order_payment WHERE payment_method_type IS NULL AND payment_method_id IS NULL);

   SET i = (select min(id) FROM taxify_payment_order.inapp_order_payment WHERE payment_method_type IS NULL AND payment_method_id IS NULL);

   SET step = 10000;

   WHILE (i <= max_id) DO

     START TRANSACTION;

     UPDATE taxify_payment_order.inapp_order_payment iop

     INNER JOIN taxify_payment_order.inapp_order io ON (iop.inapp_order_id=io.id)

     SET iop.payment_method_type = io.payment_method_type,

         iop.payment_method_id = io.payment_method_id

     WHERE  iop.payment_method_type IS NULL

       AND iop.payment_method_id IS NULL

     AND iop.id >= i

     AND iop.id <= i \+ step;

     COMMIT;

     DO SLEEP(4);

     SET i = i \+ step;

   END WHILE;

 END;

